import textwrap
def rewrap(h, first_words):
    lines = h.split('\n')
    i = next(k for k, l in enumerate(lines) if l.startswith('// ' + first_words))
    j = i
    while lines[j + 1].startswith('// ') and not lines[j + 1].startswith('// ====='):
        j += 1
    text = ' '.join(l[3:] for l in lines[i:j + 1])
    wrapped = ['// ' + w for w in textwrap.wrap(text, 77, break_long_words=False, break_on_hyphens=False)]
    return '\n'.join(lines[:i] + wrapped + lines[j + 1:])
